if($path==='/dashboard/summary'&&$method==='GET'){require_permission('dashboard.view');$pdo=db();$daily=[];foreach(['invoices','order_invoices'] as $table){$q=$pdo->query("SELECT DATE(created_at) day,COALESCE(SUM(total),0) total FROM $table WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at)");foreach($q->fetchAll() as $r){$day=(string)$r['day'];$daily[$day]=($daily[$day]??0)+(float)$r['total'];}}ksort($daily);$daily=array_map(static fn($day,$total)=>['day'=>$day,'total'=>$total],array_keys($daily),array_values($daily));$inventory=(int)$pdo->query('SELECT COALESCE(SUM(stock_units),0) FROM inventory')->fetchColumn();$inventoryProducts=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn();$stockValue=(float)$pdo->query('SELECT COALESCE(SUM(FLOOR(i.stock_units/p.units_per_box)*p.cost_price),0) FROM products p JOIN inventory i ON i.product_id=p.id WHERE p.is_active=1')->fetchColumn();$estimatedRevenue=(float)$pdo->query('SELECT COALESCE(SUM(FLOOR(i.stock_units/p.units_per_box)*p.box_price),0) FROM products p JOIN inventory i ON i.product_id=p.id WHERE p.is_active=1')->fetchColumn();$low=(int)$pdo->query('SELECT COUNT(*) FROM products p JOIN inventory i ON i.product_id=p.id WHERE p.is_active=1 AND i.stock_units<=p.reorder_level_units')->fetchColumn();$open=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status IN ('confirmed','partially_confirmed') AND payment_status='unpaid'")->fetchColumn();$submitted=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='submitted'")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM payments WHERE verification_status='pending' AND rejection_reason IS NULL")->fetchColumn();$today=(float)$pdo->query("SELECT (SELECT COALESCE(SUM(total),0) FROM invoices WHERE invoice_status='issued' AND DATE(created_at)=CURDATE())+(SELECT COALESCE(SUM(total),0) FROM order_invoices WHERE DATE(created_at)=CURDATE())")->fetchColumn();$q=$pdo->query("SELECT COUNT(*) FROM orders WHERE payment_status='paid' AND DATE(paid_at)=CURDATE()");respond(['inventory_units'=>$inventory,'inventory_products'=>$inventoryProducts,'stock_value'=>$stockValue,'estimated_revenue'=>$estimatedRevenue,'low_stock'=>$low,'open_orders'=>$open,'submitted_orders'=>$submitted,'pending_payments'=>$pending,'finance_orders'=>$open,'finance_action_count'=>$open+$pending,'today_paid'=>$today,'paid_today_count'=>(int)$q->fetchColumn(),'daily'=>$daily]);}
