  $q=$pdo->prepare("SELECT ii.product_id,ii.product_name_snapshot product_name,ii.product_code_snapshot product_code,CASE WHEN p.verification_status='approved' THEN 'paid' WHEN p.verification_status='pending' THEN 'pending' WHEN p.verification_status='rejected' OR pi.status='rejected' THEN 'rejected' ELSE 'unpaid' END status,SUM(CASE WHEN ii.selling_unit='box' THEN ii.quantity ELSE ii.quantity/NULLIF(ii.items_per_box_snapshot,0) END) boxes,SUM(CASE WHEN ii.selling_unit='box' THEN ii.quantity*ii.items_per_box_snapshot ELSE ii.quantity END) units,SUM(ii.line_total) amount FROM proforma_invoices pi LEFT JOIN payments p ON p.proforma_id=pi.id JOIN proforma_invoice_items ii ON ii.proforma_id=pi.id WHERE DATE(COALESCE(p.reviewed_at,p.submitted_at,pi.created_at)) BETWEEN ? AND ? GROUP BY ii.product_id,ii.product_name_snapshot,ii.product_code_snapshot,status");$q->execute([$from,$to]);foreach($q->fetchAll() as $r){if($status!=='all'&&$r['status']!==$status)continue;$products[]=$r;}
 }
 $grouped=[];foreach($products as $r){$id=(int)$r['product_id'];if(!isset($grouped[$id]))$grouped[$id]=['product_id'=>$id,'product_name'=>$r['product_name'],'product_code'=>$r['product_code'],'paid_boxes'=>0.0,'unpaid_boxes'=>0.0,'pending_boxes'=>0.0,'rejected_boxes'=>0.0,'total_boxes'=>0.0,'total_units'=>0,'paid_amount'=>0.0,'unpaid_amount'=>0.0,'pending_amount'=>0.0,'rejected_amount'=>0.0,'total_amount'=>0.0];$g=&$grouped[$id];$st=$r['status'];if(isset($g[$st.'_boxes']))$g[$st.'_boxes']+=(float)$r['boxes'];if(isset($g[$st.'_amount']))$g[$st.'_amount']+=(float)$r['amount'];$g['total_boxes']+=(float)$r['boxes'];$g['total_units']+=(int)$r['units'];$g['total_amount']+=(float)$r['amount'];unset($g);}
 respond(['from'=>$from,'to'=>$to,'status'=>$status,'type'=>$type,'summary'=>$summary,'records'=>$records,'products'=>array_values($grouped)]);
}
